 const [customerReply,setCustomerReply]=useState(null),[replyPending,setReplyPending]=useState(null);
 const [attachment,setAttachment]=useState(null),[attachmentEnabled,setAttachmentEnabled]=useState(true),[attachmentBusy,setAttachmentBusy]=useState(false),[attachmentError,setAttachmentError]=useState(''),[attachmentRetry,setAttachmentRetry]=useState(0),[evidenceError,setEvidenceError]=useState(''),[location,setLocation]=useState(locations[0]),[scannedLocation,setScannedLocation]=useState(locations[0].name),[lightbox,setLightbox]=useState(null);
 const lightboxRef=useRef(null);
