 async function addEvidence(file,title){if(!file||!current)return;setEvidenceError('');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){setEvidenceError('Choose a JPG, PNG or WebP image under 5 MB.');return}try{const image=await createImageBitmap(file);const scale=Math.min(1,900/image.width,900/image.height);const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);image.close();const src=canvas.toDataURL('image/jpeg',.65);const updated={...current,evidence:{...current.evidence,[title]:{src,kind:'reviewer',note:'',device:'Not specified',viewportWidth:'',viewportHeight:'',reproduction:''}}};setCurrent(updated);persist(updated)}catch{setEvidenceError('This image could not be opened. Try another screenshot.')}}
